 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, color))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            pieces.append(cells)

    # Slide objects right, settling rightmost objects first.
    pieces.sort(key=lambda cells: max(c for _, c, _ in cells), reverse=True)
    out = [[0] * w for _ in range(h)]
    for cells in pieces:
        shift = 0
        while True:
            step = shift + 1
            if any(c + step >= w or out[r][c + step] != 0 for r, c, _ in cells):
                break
            shift = step
        for r, c, color in cells:
            out[r][c + shift] = color
    return out
